public class Main {
    public static void main(String[] args) {
        IntStack plates = new IntStack(5);
        plates.push(10);
        plates.push(20);
        plates.push(30);
        System.out.println("Top plate: " + plates.peek());
        System.out.println("Took: " + plates.pop());
        System.out.println("Took: " + plates.pop());
        plates.push(40);
        System.out.println("Top plate now: " + plates.peek());
    }
}

class IntStack {
    int[] items;
    int top = -1; // index of the top item; -1 means empty

    IntStack(int capacity) {
        items = new int[capacity];
    }

    void push(int value) {
        top++;
        items[top] = value;
    }

    int pop() {
        int value = items[top];
        top--;
        return value;
    }

    int peek() {
        return items[top];
    }
}
